CP=$(mvn -pl sm-core -q dependency:build-classpath -DincludeScope=compile -Dmdep.outputFile=/dev/stdout) && CP="sm-core/target/classes:$CP" && cat > /tmp/PriceCheck.java << 'EOF'
import java.math.BigDecimal;
import java.util.Calendar;
import java.util.Date;
import java.util.HashSet;
import com.salesmanager.core.business.utils.ProductPriceUtils;
import com.salesmanager.core.model.catalog.product.availability.ProductAvailability;
import com.salesmanager.core.model.catalog.product.price.FinalPrice;
import com.salesmanager.core.model.catalog.product.price.ProductPrice;

public class PriceCheck {
  static Date days(int d) {
    Calendar c = Calendar.getInstance();
    c.add(Calendar.DATE, d);
    return c.getTime();
  }
  static boolean discounted(Date start, Date end) throws Exception {
    ProductPrice price = new ProductPrice();
    price.setDefaultPrice(true);
    price.setProductPriceAmount(new BigDecimal("20"));
    price.setProductPriceSpecialAmount(new BigDecimal("10"));
    price.setProductPriceSpecialStartDate(start);
    price.setProductPriceSpecialEndDate(end);
    ProductAvailability a = new ProductAvailability();
    a.setRegion("*");
    a.setPrices(new HashSet<>());
    a.getPrices().add(price);
    price.setProductAvailability(a);
    FinalPrice fp = new ProductPriceUtils().getFinalPrice(a);
    System.out.println("start=" + start + " end=" + end + " discounted=" + fp.isDiscounted() + " final=" + fp.getFinalPrice());
    return fp.isDiscounted();
  }
  public static void main(String[] args) throws Exception {
    boolean ok = true;
    ok &= discounted(null, null);
    ok &= discounted(days(-2), days(10));
    ok &= discounted(null, days(10));
    ok &= !discounted(days(-10), days(-1));
    ok &= !discounted(days(2), days(10));
    System.out.println(ok ? "PASS" : "FAIL");
    if (!ok) System.exit(1);
  }
}
EOF
javac -cp "$CP" -d /tmp /tmp/PriceCheck.java && java -cp "/tmp:$CP" PriceCheck
